"""Merchant-facing presentation for Pakgat onboarding.

Business/integration provider details remain internal. Merchants see the Pakgat
partnership flow and Nafath identity verification only.
"""

from app import application as core
from app import merchant_onboarding as onboarding

LOGO = "data:image/webp;base64,"

